package com.hbm.blocks.machine.rbmk;
import com.hbm.api.block.IToolable; import com.hbm.tileentity.ModRBMKBlockEntities; import com.hbm.tileentity.machine.rbmk.BlockEntityRBMKGauge; import net.minecraft.core.BlockPos; import net.minecraft.core.Direction; import net.minecraft.world.InteractionHand; import net.minecraft.world.entity.player.Player; import net.minecraft.world.level.Level; import net.minecraft.world.level.block.EntityBlock; import net.minecraft.world.level.block.entity.BlockEntity; import net.minecraft.world.level.block.entity.BlockEntityTicker; import net.minecraft.world.level.block.entity.BlockEntityType; import net.minecraft.world.level.block.state.BlockState; import net.minecraft.world.phys.Vec3; import org.jspecify.annotations.Nullable; import java.util.function.Consumer;
import dev.golem.core.registry.TickingBlock;
public class RBMKGauge extends RBMKMiniPanelBase implements IToolable, TickingBlock { public static Consumer<BlockEntityRBMKGauge> OPEN_SCREEN = gauge -> {}; public RBMKGauge(Properties props) { super(props); } @Override public boolean onScrew(Level level, Player player, BlockPos pos, Direction side, Vec3 hit, InteractionHand hand, ToolType tool) { if (tool != ToolType.SCREWDRIVER) return false; if (level.isClientSide() && level.getBlockEntity(pos) instanceof BlockEntityRBMKGauge gauge) OPEN_SCREEN.accept(gauge); return true; } @Override public @Nullable BlockEntity newBlockEntity(BlockPos pos, BlockState state) { return new BlockEntityRBMKGauge(pos, state); } }
